'people.over65': ['Adults over 65', 'Adultos mayores de 65', 'Adultos acima de 65'],
'people.sheltered': ['Staying here tonight?', '¿Se aloja aquí esta noche?', 'Vai ficar aqui hoje?'],
'people.immediateNeeds': ['Immediate needs', 'Necesidades inmediatas', 'Necessidades imediatas'],
'people.register': ['Register', 'Registrar', 'Registrar'],
'people.registered': ['Registered · {ref}', 'Registrado · {ref}', 'Registrado · {ref}'],
