'wiz.copyWa': ['Copy the WhatsApp message', 'Copiar el mensaje de WhatsApp', 'Copiar a mensagem de WhatsApp'],
'wiz.sameQr': ['That QR is real — scan it with a phone camera.', 'Ese QR es real — escanéelo con la cámara.', 'Esse QR é real — escaneie com a câmera.'],
'wiz.goLive': ['Go live', 'Publicar', 'Publicar'],
